import{_ as a,o as t,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"ATLAS Icon Studio","description":"Manage, import, delete and save Home Assistant icon sets with ATLAS Icon Studio.","frontmatter":{"title":"ATLAS Icon Studio","description":"Manage, import, delete and save Home Assistant icon sets with ATLAS Icon Studio."},"headers":[],"relativePath":"en/projects/atlas-plugins/icon-studio.md","filePath":"en/projects/atlas-plugins/icon-studio.md","lastUpdated":1792754181000}'),i={name:"en/projects/atlas-plugins/icon-studio.md"};function s(r,e,c,d,l,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="atlas-icon-studio" tabindex="-1">ATLAS Icon Studio <a class="header-anchor" href="#atlas-icon-studio" aria-label="Permalink to &quot;ATLAS Icon Studio&quot;">​</a></h1><p>ATLAS Icon Studio is a separately installed plugin for creating and managing Home Assistant icon sets with the <code>atlas:</code> prefix. Version 0.1.15 supports large collections without a fixed icon-count limit; the list renders 24 entries at a time.</p><h2 id="managing-icons" tabindex="-1">Managing icons <a class="header-anchor" href="#managing-icons" aria-label="Permalink to &quot;Managing icons&quot;">​</a></h2><p>Current plugin version: <strong>0.1.17</strong>. It fixes a missing validator import when creating drawing text. Version 0.1.16 previously fixed export-selector startup. Storage formats remain unchanged.</p><p>The collection is stored in browser-local IndexedDB. Older local data is adopted; export the collection as JSON before changing browser or address.</p><h2 id="drawing-and-image-previews" tabindex="-1">Drawing and image previews <a class="header-anchor" href="#drawing-and-image-previews" aria-label="Permalink to &quot;Drawing and image previews&quot;">​</a></h2><p>A separate drawing area supports colored SVGs with shapes, freehand and text, layer ordering and up to ten undo/redo steps. Save as exports SVG, PNG or WebP, optionally with a transparent background. Raster images can be previewed and optionally traced, but do not directly become <code>atlas:</code> icons; HA icon sets need SVG paths. File Studio can hand supported images directly to Icon Studio on the same ATLAS server. Downloads are not automatically copied to HA.</p><h2 id="editing-a-collection" tabindex="-1">Editing a collection <a class="header-anchor" href="#editing-a-collection" aria-label="Permalink to &quot;Editing a collection&quot;">​</a></h2><p>Select an icon in the collection and use <strong>Delete icon</strong> to remove it. Icon Studio automatically selects the next deletable icon, so you can remove several icons in succession without selecting each one again. The reference icon <code>atlas:home</code> is protected and cannot be deleted. At least one icon remains in the collection.</p><p>Search, keyboard navigation and export cover the full collection, even when only a small portion is visible. Collections can be backed up and restored as JSON; name conflicts can be replaced, skipped or renamed automatically.</p><h2 id="home-assistant" tabindex="-1">Home Assistant <a class="header-anchor" href="#home-assistant" aria-label="Permalink to &quot;Home Assistant&quot;">​</a></h2><p>Icon sets can be exported locally as <code>atlas-iconset.js</code> or read directly from <code>/config/www/atlas-iconset.js</code> through File Studio. When saving, you can replace the existing file; File Studio creates a backup first. Alternatively, Icon Studio creates a new numbered file and displays its <code>/local/...</code> resource path for registration in Home Assistant. Direct access requires <code>/config/www</code> to be approved in File Studio.</p><p>See the <a href="https://github.com/rockbaer2007/atlas-icon-studio-plugin#readme" target="_blank" rel="noreferrer">plugin README</a> for installation, format and path details.</p><h2 id="safe-plugin-recovery" tabindex="-1">Safe plugin recovery <a class="header-anchor" href="#safe-plugin-recovery" aria-label="Permalink to &quot;Safe plugin recovery&quot;">​</a></h2><p>Back up the collection as JSON, export the iconset and save drawings separately as SVG. In <strong>Administration → Plugin Manager → Icon Studio → Restore</strong>, select a backup, review version/compatibility and use the action that backs up the current plugin and applies the selected version. Cancel leaves it unchanged.</p><div class="info custom-block"><p class="custom-block-title">Isolated qualification on 2026-10-16</p><p>ATLAS 0.1.312 passed <strong>0.1.16 → 0.1.17</strong> and recovery <strong>0.1.17 → 0.1.16 → saved 0.1.17</strong>, including App restart. All twelve assets matched their actual packages. A collection of 131 icons and a drawing with two text objects survived on the same browser origin/profile. Re-exported JSON, iconset JavaScript and SVG were byte-identical. New text creation, duplicate and undo worked. Test files, existing iconset, project, another plugin, trash and history remained intact. Repositories, server data and browser exports were backed up beforehand. <strong>Pi 5 and Proxmox were neither queried nor changed in this isolated test.</strong> Data-format migrations remain separate.</p></div><div class="info custom-block"><p class="custom-block-title">Pi 5 and Proxmox qualification on 2026-10-16</p><p>After fresh local HA backups, PC file copies and browser exports, Administration passed <strong>0.1.16 → 0.1.17 → original 0.1.16 → 0.1.17</strong>. All twelve package assets match; settings, existing files, six active plugins, project, trash and history remain intact. ATLAS 0.1.312 and HA 2026.10.1 needed no restart. Both hosts finish with Icon Studio 0.1.17. If a stale update preview is rejected after recovery, reload Administration and select the update again. Direct access and HA Ingress were checked on each host: three reference icons and an empty drawing draft in each context. Collection JSON stays byte-identical, and the draft is unchanged after reload. Text creation and undo work. Larger collections and populated drawings were covered by the isolated test.</p></div><p>Package recovery does not restore deleted browser data. IndexedDB and the local drawing draft belong to the browser profile and origin (scheme, host and port). HA/server backups do not contain those browser stores. Collection JSON and iconset JavaScript exclude colored drawings; an exported SVG is not a complete editable-draft/undo backup. Current draft shapes and filename persist locally; tool selection, search and undo/redo history belong to the session.</p>',18)])])}const g=a(i,[["render",s]]);export{u as __pageData,g as default};
